// Compiled only into the netstandard2.1 build. The project removes this file from
// every other target, the way dotnet/runtime conditions its own polyfills, so the
// rule lives in the project file and not in a #if here.
//
// This file holds only the framework APIs netstandard2.1 lacks that this project
// calls. The compiler-required types (IsExternalInit and
// CallerArgumentExpressionAttribute) are generated by PolySharp; see
// Directory.Build.props.

namespace Hyperbee.XS.Internal;

/// <summary>
/// Stands in for the <c>ICollection&lt;T&gt;.AddRange</c> extension added to
/// <c>System.Collections.Generic.CollectionExtensions</c> in .NET 10.
/// </summary>
/// <remarks>
/// Compiled only for netstandard2.1, so on net10.0 and net11.0 the framework method is
/// the single candidate and there is no CS0121 ambiguity.
/// </remarks>
internal static class CollectionAddRangeExtensions
{
    public static void AddRange<T>( this ICollection<T> collection, IEnumerable<T> source )
    {
        if ( collection is null )
            throw new ArgumentNullException( nameof( collection ) );

        if ( source is null )
            throw new ArgumentNullException( nameof( source ) );

        foreach ( var item in source )
            collection.Add( item );
    }
}
